mapper.insert:
INSERT INTO sql_definition_history (
    sql_def_id, version, sql_text, assert_type, assert_op, assert_value, assert_config, cron_expr,
    changed_by, changed_at, change_type
) VALUES (
    #{sqlDefId}, #{version}, #{sqlText}, #{assertType}, #{assertOp}, #{assertValue},
    CAST(#{assertConfig,jdbcType=VARCHAR} AS jsonb),
    #{cronExpr}, #{changedBy}, now(), #{changeType}
)

mapper.select:
SELECT t.*, count(*) OVER () AS total_count
FROM (
    SELECT * FROM sql_definition_history
    WHERE sql_def_id = #{sqlDefId}

        AND changed_at::date = CAST(#{day} AS date)

    ORDER BY version DESC, id DESC
    LIMIT #{limit} OFFSET #{offset}
) t
